Based on the commit message, the root cause and the patch provided below, you need to:

1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
wifi: b43legacy: enforce bounds check on firmware key index
 in RX path

Same fix as b43: the firmware-controlled key index in b43legacy_rx()
can exceed dev->max_nr_keys. The existing B43legacy_WARN_ON is
non-enforcing in production builds, allowing an out-of-bounds read of
dev->key[].

Make the check enforcing by dropping the frame for invalid indices.

Fixes: 75388acd0cd8 ("[B43LEGACY]: add mac80211-based driver for legacy BCM43xx devices")
Cc: stable@vger.kernel.org
Signed-off-by: Tristan Madani <tristan@talencesecurity.com>
Link: https://patch.msgid.link/20260417111145.2694196-2-tristmd@gmail.com
Signed-off-by: Johannes Berg <johannes.berg@intel.com>

Here is the root cause:
The firmware-controlled key index in the RX path can exceed `dev->max_nr_keys`, and the existing `B43legacy_WARN_ON` macro only produces a warning in debug builds without preventing the subsequent out-of-bounds read of `dev->key[]`, leading to a potential security vulnerability.

Here is the patch:

 void b43legacy_rx(struct b43legacy_wldev *dev,
 		  struct sk_buff *skb,
 		  const void *_rxhdr)
 {
 	struct ieee80211_rx_status status;
 	struct b43legacy_plcp_hdr6 *plcp;
 	struct ieee80211_hdr *wlhdr;
 	const struct b43legacy_rxhdr_fw3 *rxhdr = _rxhdr;
 	__le16 fctl;
 	u16 phystat0;
 	u16 phystat3;
 	u16 chanstat;
 	u16 mactime;
 	u32 macstat;
 	u16 chanid;
 	u8 jssi;
 	int padding;

 	memset(&status, 0, sizeof(status));

 	/* Get metadata about the frame from the header. */
 	phystat0 = le16_to_cpu(rxhdr->phy_status0);
 	phystat3 = le16_to_cpu(rxhdr->phy_status3);
 	jssi = rxhdr->jssi;
 	macstat = le16_to_cpu(rxhdr->mac_status);
 	mactime = le16_to_cpu(rxhdr->mac_time);
 	chanstat = le16_to_cpu(rxhdr->channel);

 	if (macstat & B43legacy_RX_MAC_FCSERR)
 		dev->wl->ieee_stats.dot11FCSErrorCount++;

 	/* Skip PLCP and padding */
 	padding = (macstat & B43legacy_RX_MAC_PADDING) ? 2 : 0;
 	if (unlikely(skb->len < (sizeof(struct b43legacy_plcp_hdr6) +
 	    padding))) {
 		b43legacydbg(dev->wl, "RX: Packet size underrun (1)\n");
 		goto drop;
 	}
 	plcp = (struct b43legacy_plcp_hdr6 *)(skb->data + padding);
 	skb_pull(skb, sizeof(struct b43legacy_plcp_hdr6) + padding);
 	/* The skb contains the Wireless Header + payload data now */
 	if (unlikely(skb->len < (2+2+6/*minimum hdr*/ + FCS_LEN))) {
 		b43legacydbg(dev->wl, "RX: Packet size underrun (2)\n");
 		goto drop;
 	}
 	wlhdr = (struct ieee80211_hdr *)(skb->data);
 	fctl = wlhdr->frame_control;

 	if ((macstat & B43legacy_RX_MAC_DEC) &&
 	    !(macstat & B43legacy_RX_MAC_DECERR)) {
 		unsigned int keyidx;
 		int wlhdr_len;
 		int iv_len;
 		int icv_len;

 		keyidx = ((macstat & B43legacy_RX_MAC_KEYIDX)
 			  >> B43legacy_RX_MAC_KEYIDX_SHIFT);
 		/* We must adjust the key index here. We want the "physical"
 		 * key index, but the ucode passed it slightly different.
 		 */
 		keyidx = b43legacy_kidx_to_raw(dev, keyidx);
-		B43legacy_WARN_ON(keyidx >= dev->max_nr_keys);
+		if (B43legacy_WARN_ON(keyidx >= dev->max_nr_keys))
+			goto drop;

 		if (dev->key[keyidx].algorithm != B43legacy_SEC_ALGO_NONE) {
 			/* Remove PROTECTED flag to mark it as decrypted. */
 			B43legacy_WARN_ON(!ieee80211_has_protected(fctl));
 			fctl &= ~cpu_to_le16(IEEE80211_FCTL_PROTECTED);
 			wlhdr->frame_control = fctl;

 			wlhdr_len = ieee80211_hdrlen(fctl);
 			if (unlikely(skb->len < (wlhdr_len + 3))) {
 				b43legacydbg(dev->wl, "RX: Packet size"
 					     " underrun3\n");
 				goto drop;
 			}
 			if (skb->data[wlhdr_len + 3] & (1 << 5)) {
 				/* The Ext-IV Bit is set in the "KeyID"
 				 * octet of the IV.
 				 */
 				iv_len = 8;
 				icv_len = 8;
 			} else {
 				iv_len = 4;
 				icv_len = 4;
 			}
 			if (unlikely(skb->len < (wlhdr_len + iv_len +
 			    icv_len))) {
 				b43legacydbg(dev->wl, "RX: Packet size"
 					     " underrun4\n");
 				goto drop;
 			}
 			/* Remove the IV */
 			memmove(skb->data + iv_len, skb->data, wlhdr_len);
 			skb_pull(skb, iv_len);
 			/* Remove the ICV */
 			skb_trim(skb, skb->len - icv_len);

 			status.flag |= RX_FLAG_DECRYPTED;
 		}
 	}

 	status.signal = b43legacy_rssi_postprocess(dev, jssi,
 				      (phystat0 & B43legacy_RX_PHYST0_OFDM),
 				      (phystat0 & B43legacy_RX_PHYST0_GAINCTL),
 				      (phystat3 & B43legacy_RX_PHYST3_TRSTATE));
 	/* change to support A PHY */
 	if (phystat0 & B43legacy_RX_PHYST0_OFDM)
 		status.rate_idx = b43legacy_plcp_get_bitrate_idx_ofdm(plcp, false);
 	else
 		status.rate_idx = b43legacy_plcp_get_bitrate_idx_cck(plcp);
 	status.antenna = !!(phystat0 & B43legacy_RX_PHYST0_ANT);

 	/*
 	 * All frames on monitor interfaces and beacons always need a full
 	 * 64-bit timestamp. Monitor interfaces need it for diagnostic
 	 * purposes and beacons for IBSS merging.
 	 * This code assumes we get to process the packet within 16 bits
 	 * of timestamp, i.e. about 65 milliseconds after the PHY received
 	 * the first symbol.
 	 */
 	if (ieee80211_is_beacon(fctl) || dev->wl->radiotap_enabled) {
 		u16 low_mactime_now;

 		b43legacy_tsf_read(dev, &status.mactime);
 		low_mactime_now = status.mactime;
 		status.mactime = status.mactime & ~0xFFFFULL;
 		status.mactime += mactime;
 		if (low_mactime_now <= mactime)
 			status.mactime -= 0x10000;
 		status.flag |= RX_FLAG_MACTIME_START;
 	}

 	chanid = (chanstat & B43legacy_RX_CHAN_ID) >>
 		  B43legacy_RX_CHAN_ID_SHIFT;
 	switch (chanstat & B43legacy_RX_CHAN_PHYTYPE) {
 	case B43legacy_PHYTYPE_B:
 	case B43legacy_PHYTYPE_G:
 		status.band = NL80211_BAND_2GHZ;
 		status.freq = chanid + 2400;
 		break;
 	default:
 		b43legacywarn(dev->wl, "Unexpected value for chanstat (0x%X)\n",
 		       chanstat);
 		goto drop;
 	}

 	memcpy(IEEE80211_SKB_RXCB(skb), &status, sizeof(status));
 	ieee80211_rx_irqsafe(dev->wl->hw, skb);

 	return;
 drop:
 	b43legacydbg(dev->wl, "RX: Packet dropped\n");
 	dev_kfree_skb_any(skb);
 }



